class Solution {
    public: int maxHeight(vector<vector<int>>& cuboids){
        for(auto& cuboid:cuboids)sort(cuboid.begin(),cuboid.end());
        sort(cuboids.begin(),cuboids.end());
        vector<int> dp(cuboids.size());
        int answer=0;
        for(int i=0;i<(int)cuboids.size();++i){
            dp[i]=cuboids[i][2];
            for(int j=0;j<i;++j)if(cuboids[j][0]<=cuboids[i][0]&&cuboids[j][1]<=cuboids[i][1]&&cuboids[j][2]<=cuboids[i][2])dp[i]=max(dp[i],dp[j]+cuboids[i][2]);
            answer=max(answer,dp[i]);
        }
        return answer;
    }
};
